import { z } from 'zod';
import {
  hexColorSchema,
  optionalText,
  positiveMoneySchema,
  uuidSchema,
} from '../common/schemas.js';
import { GOAL_TEMPLATES } from '../database/reference-data.js';

const templateKeySchema = z.enum(
  GOAL_TEMPLATES.map((template) => template.key) as [string, ...string[]],
);
const emojiSchema = z.string().trim().min(1).max(8);
const calendarDateSchema = z.iso.date();

export const goalStatusSchema = z.enum([
  'active',
  'paused',
  'completed',
  'archived',
]);

export const createGoalSchema = z.object({
  /** Generated by the app, so an offline create can be retried safely */
  id: uuidSchema,
  title: z.string().trim().min(1).max(120),
  templateKey: templateKeySchema.optional(),
  /** Defaults to the template's, or 🎯 */
  emoji: emojiSchema.optional(),
  color: hexColorSchema.optional(),
  targetAmount: positiveMoneySchema,
  /** Defaults to the user's base currency */
  currency: z
    .string()
    .trim()
    .length(3)
    .transform((code) => code.toUpperCase())
    .optional(),
  /** `YYYY-MM-DD`, today or later */
  deadline: calendarDateSchema.optional(),
  /** Savings account where the money physically sits; same currency as the goal */
  linkedAccountId: uuidSchema.optional(),
});
export type CreateGoalInput = z.infer<typeof createGoalSchema>;

export const updateGoalSchema = z
  .object({
    title: z.string().trim().min(1).max(120),
    emoji: emojiSchema,
    color: hexColorSchema,
    targetAmount: positiveMoneySchema,
    deadline: calendarDateSchema.nullable(),
    linkedAccountId: uuidSchema.nullable(),
    /** pause, resume, complete, archive or bring back */
    status: goalStatusSchema,
    isPrimary: z.literal(true),
  })
  .partial()
  .refine((patch) => Object.keys(patch).length > 0, 'Nothing to update');
export type UpdateGoalInput = z.infer<typeof updateGoalSchema>;

export const contributionSchema = z.object({
  /** Generated by the app, so a retried deposit is not counted twice */
  id: uuidSchema,
  type: z.enum(['deposit', 'withdrawal']),
  /** In the goal's currency */
  amount: positiveMoneySchema,
  /** Account the money comes from (deposit) or goes to (withdrawal); none = not tracked */
  accountId: uuidSchema.optional(),
  /** What the account pays or gets, in its currency, when it differs from the goal's */
  accountAmount: positiveMoneySchema.optional(),
  note: optionalText(255).optional(),
});
export type ContributionInput = z.infer<typeof contributionSchema>;

export const listGoalsQuerySchema = z.object({
  status: goalStatusSchema.optional(),
});

export const listContributionsQuerySchema = z.object({
  cursor: z.string().max(200).optional(),
  limit: z.coerce.number().int().min(1).max(200).default(50),
});

export const templatesQuerySchema = z.object({
  language: z.enum(['uz', 'ru', 'en']).optional(),
});
